CREATE TABLE IF NOT EXISTS campus_api_credential(merchant_id BIGINT PRIMARY KEY,public_id VARCHAR(36) NOT NULL UNIQUE,secret VARCHAR(64) NOT NULL,enabled TINYINT NOT NULL DEFAULT 0,allow_recharge TINYINT NOT NULL DEFAULT 0,allow_pay TINYINT NOT NULL DEFAULT 1,callback_url VARCHAR(500) NOT NULL DEFAULT '',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_api_nonce(public_id VARCHAR(36) NOT NULL,nonce VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(public_id,nonce)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS campus_api_order(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(48) NOT NULL UNIQUE,merchant_id BIGINT NOT NULL,request_id VARCHAR(64) NOT NULL,payload_hash VARCHAR(64) NOT NULL,trade_type VARCHAR(12) NOT NULL,card_no VARCHAR(34) NOT NULL,amount DECIMAL(12,2) NOT NULL,occurred_at DATETIME NOT NULL,location VARCHAR(200) NOT NULL,description VARCHAR(500) NOT NULL,local_serial VARCHAR(64) NULL,status VARCHAR(16) NOT NULL DEFAULT 'NEW',ledger_id BIGINT NULL,error_message VARCHAR(300) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,UNIQUE KEY uk_api_request(merchant_id,request_id),UNIQUE KEY uk_api_serial(merchant_id,local_serial),UNIQUE KEY uk_api_ledger(ledger_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_api_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,trace_id VARCHAR(36) NOT NULL,public_id VARCHAR(36) NULL,order_no VARCHAR(48) NULL,action VARCHAR(32) NOT NULL,code VARCHAR(40) NOT NULL,message VARCHAR(300) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY ix_api_log(order_no,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_api_outbox(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(48) NOT NULL UNIQUE,merchant_id BIGINT NOT NULL,body TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_at DATETIME NOT NULL,locked_at DATETIME NULL,last_error VARCHAR(300) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
